'use strict';
(function(root){
const EARTH_KM=6371.0088,KNOT_MPS=1852/3600,RAD=Math.PI/180;
const PRODUCTS=['AMV-LLlow','AMV-LLmid'];
function timeISO(time){const m=/^(\d{4})(\d{2})(\d{2})[._](\d{2})(\d{2})(\d{2})$/.exec(time);if(!m)return null;const iso=`${m[1]}-${m[2]}-${m[3]}T${m[4]}:${m[5]}:${m[6]}Z`;const d=new Date(iso);return Number.isFinite(+d)&&d.toISOString().slice(0,19)===iso.slice(0,19)?iso:null;}
function windComponents(knots,fromDegrees){const r=fromDegrees*RAD;return {u:-knots*KNOT_MPS*Math.sin(r),v:-knots*KNOT_MPS*Math.cos(r)};}
function pressureHeight(hPa){return 44.330*(1-Math.pow(hPa/1013.25,.190263));}
function wrapLon(lon){return ((lon+180)%360+360)%360-180;}
// Constant local east/north velocity on a sphere (rhumb-line integration).
// No force model, condensation, or forecast. Valid for this short bounded demonstration.
function advect(point,seconds){const phi0=point.lat*RAD;const phi=Math.max(-85*RAD,Math.min(85*RAD,phi0+point.v*seconds/(EARTH_KM*1000)));const delta=Math.abs(point.v)>.00001?(point.u/point.v)*Math.log(Math.tan(Math.PI/4+phi/2)/Math.tan(Math.PI/4+phi0/2)):point.u*seconds/(EARTH_KM*1000*Math.cos(phi0));return {lat:phi/RAD,lon:wrapLon(point.lon+delta/RAD)};}
function normalize(collection,product,time){if(!PRODUCTS.includes(product)||!timeISO(time)||collection?.type!=='FeatureCollection'||!Array.isArray(collection.features))throw Error('AMVデータの形式が不正です');const expected=timeISO(time).slice(0,19);const cells=new Map();let matching=0,old=0,invalid=0;for(const f of collection.features){const p=f.properties||{},xy=f.geometry?.coordinates;if(f.geometry?.type!=='Point'||!Array.isArray(xy)){invalid++;continue;}if(p.DAY+'T'+p.TIME!==expected){old++;continue;}const [lon,lat]=xy.map(Number),knots=Number(p.SPD),from=Number(p.DIR),pressure=Number(p.PRE);if(![lat,lon,knots,from,pressure].every(Number.isFinite)||p.SPD==null||p.DIR==null||p.PRE==null||String(p.SPD).trim()===''||String(p.DIR).trim()===''||String(p.PRE).trim()===''||Math.abs(lat)>75||Math.abs(lon)>180||knots<0||knots>250||from<0||from>360||pressure<600||pressure>950){invalid++;continue;}if(p.RE_PRODUCT_ID&&p.RE_PRODUCT_ID!==product){invalid++;continue;}if(product==='AMV-LLlow'&&pressure<800||product==='AMV-LLmid'&&pressure>=800){invalid++;continue;}matching++;const ix=Math.floor((lon+180)/2),iy=Math.floor((lat+90)/2);const key=ix+':'+iy;const score=(lon-(-179+2*ix))**2+(lat-(-89+2*iy))**2;const existing=cells.get(key);if(!existing||score<existing.score)cells.set(key,{score,point:{lat,lon,knots,from,pressure,...windComponents(knots,from),altitudeKm:pressureHeight(pressure),product}});}
if(!cells.size)throw Error('指定時刻の有効な観測風がありません');return {points:[...cells.values()].map(x=>x.point),matching,old,invalid};}
function validateBundle(bundle){if(!timeISO(bundle?.time)||!Array.isArray(bundle.points)||!bundle.points.length||bundle.points.length>16000)throw Error('観測風を確認できません');for(const p of bundle.points){if(!PRODUCTS.includes(p.product)||![p.lon,p.lat,p.u,p.v,p.pressure,p.altitudeKm,p.knots,p.from].every(Number.isFinite)||Math.abs(p.lon)>180||Math.abs(p.lat)>75||p.pressure<600||p.pressure>950||p.knots<0||p.knots>250||p.from<0||p.from>360)throw Error('不正な観測風があります');const expected=windComponents(p.knots,p.from);if(Math.abs(p.u-expected.u)>.001||Math.abs(p.v-expected.v)>.001||Math.abs(p.altitudeKm-pressureHeight(p.pressure))>.001)throw Error('観測風の単位が一致しません');}return bundle;}
function latestCommon(metadata){const sets=PRODUCTS.map(id=>new Set((metadata.find(p=>p.id===id)?.times||[]).filter(timeISO)));const times=[...sets[0]].filter(t=>sets.every(s=>s.has(t))).sort();if(!times.length)throw Error('各高度で共通する観測時刻がありません');return times.at(-1);}
const api={EARTH_KM,KNOT_MPS,PRODUCTS,timeISO,windComponents,pressureHeight,wrapLon,advect,normalize,validateBundle,latestCommon};root.CloudModel=api;if(typeof module!=='undefined')module.exports=api;
})(typeof window==='undefined'?globalThis:window);
